// Captures what the Admin player write routes put on the wire and leave in the database, by running the real Admin
// Route Handlers (apps/admin/src/app/api/players) and the real @rotra/db services (Prisma) against a throwaway local
// Postgres. The harness is capture-writes-base.mjs; the Go side is apps/api/internal/writetest. Groups:
//   playerverify   PATCH /api/players/{playerId}/verification
//   playercreate   POST  /api/players                      (Add player)
//   playeredit     PATCH /api/players/{playerId}           (Edit: profile, RTR ID, email, password; shared entries)
//
//   docker run -d --rm --name rotra-capture-pg -e POSTGRES_PASSWORD=test -p 127.0.0.1:55461:5432 postgres:16-alpine
//   source ~/.nvm/nvm.sh && nvm use
//   ROTRA_CAPTURE_DB_URL=postgres://postgres:test@127.0.0.1:55461/postgres \
//     node node_modules/.pnpm/vitest@*/node_modules/vitest/vitest.mjs run --config apps/api/testdata/tools/vitest.capture.config.mjs apps/api/testdata/tools/capture-writes-players.test.mjs [-t playerverify]
//
// Refuses any host but 127.0.0.1/localhost. It creates its own database (rotra_capture_<n>) and drops it.
// The cases and the seed are generated by gen-writes-admin-players-cases.py. Output:
// apps/api/internal/adminwrites/testdata/<group>.golden.json.
//
// Two things are replaced, and only these:
//   verifySubject   answers the step's subject (a step with none is signed out), so loadAccountContext (the
//                   active-admin check) and every service run for real;
//   the provider calls of the Edit route: setPlayerPasswordByAdmin (succeeds), and supabaseProviderAdmin().readLogin
//                   and updateLogin, which keep the email of each login in memory. There is no Supabase here, and
//                   unmocked the password and the email of an edit would only ever be warnings. The mock answers as
//                   the provider does: the login has the contact's email until an update, then the proposed one; an
//                   update to 'taken@example.test' is refused (provider_rejected), as a provider refuses an email
//                   another login has. The Go side has no provider: the login is auth_identities, the same
//                   transaction changes its key (see the plan's deviations log). The shared snapshot therefore does
//                   not hold auth_provider, auth_subject or the identities.
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, test, vi } from 'vitest'
import { captureWrites, openCaptureDb, root } from './capture-writes-base.mjs'

vi.mock('../../../../packages/db/src/auth/supabase.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  verifySubject: async () => {
    const { currentSubject } = await import('./capture-writes-base.mjs')
    const subject = currentSubject()
    return subject ? { provider: 'supabase', subject } : null
  },
}))

vi.mock('../../../../packages/db/src/auth/supabase-provider-admin.ts', async (importOriginal) => {
  const { ProviderError } = await import('../../../../packages/db/src/auth/provider-admin.ts')
  // subject -> { email, operationRef }; a login only counts while its staged operation row exists (every case reseeds)
  const logins = new Map()
  return {
    ...(await importOriginal()),
    setPlayerPasswordByAdmin: async () => {},
    supabaseProviderAdmin: () => ({
      async readLogin(subject) {
        const db = globalThis.__captureDb
        const known = logins.get(subject)
        if (known) {
          const { rows } = await db.query('SELECT 1 FROM admin_player_email_edits WHERE id = $1', [known.operationRef])
          if (rows.length) return { email: known.email, phoneE164: null }
          logins.delete(subject)
        }
        const { rows } = await db.query(
          'SELECT c.email FROM player_accounts a JOIN player_private_contacts c ON c.player_id = a.player_id WHERE a.auth_subject = $1',
          [subject],
        )
        return rows.length ? { email: rows[0].email, phoneE164: null } : null
      },
      async updateLogin({ operationRef, subject, email }) {
        if (email === 'taken@example.test') throw new ProviderError('provider_rejected')
        logins.set(subject, { email, operationRef })
      },
    }),
  }
})

const here = dirname(fileURLToPath(import.meta.url))
const testdata = resolve(here, '../../internal/adminwrites/testdata')
const apiDir = resolve(root, 'apps/admin/src/app/api')

let capture
beforeAll(async () => {
  capture = await openCaptureDb()
  globalThis.__captureDb = capture.db
})
afterAll(async () => {
  await capture?.close()
})

for (const name of ['playerverify', 'playercreate', 'playeredit']) {
  test(name, async () => {
    await captureWrites({ db: capture.db, testdata, name, apiDir })
  })
}
